"""Robot-as-a-service lettering trajectory for RoboPaint-strict / eai-standard/2.2."""
import math, pathlib, sys
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

OUT = pathlib.Path('/app/output')
r = Robot()
spec = r.spec()
DOWN = np.array([0., 1., 0., 0.])  # nib points down; edge along world -y


def quat_yaw(yaw):
    # Rz(yaw) * Rx(pi): rotates the broad edge in the paper plane.
    return np.array([0., math.cos(yaw), math.sin(yaw), 0.])


def pose(x, y, z, yaw=0.):
    return [float(x), float(y), float(z), *quat_yaw(yaw)]


def linear_poses(start, end, spacing=0.003):
    a, b = np.asarray(start, float), np.asarray(end, float)
    d = np.linalg.norm(b[:3] - a[:3])
    n = max(1, int(math.ceil(d / spacing)))
    return np.array([a + (b-a)*(i/n) for i in range(1, n+1)], dtype=np.float32)


def send_path(poses, note='', spacing=0.003, video='none'):
    """Stream a pose path at 20 Hz; each target step is short enough to avoid speed clipping."""
    if len(poses) == 0:
        return None
    result = None
    # Max 400 rows / call. Preserve continuity while chunking.
    for start in range(0, len(poses), 400):
        chunk = np.asarray(poses[start:start+400], dtype=np.float32)
        result = r.submit('ee_pose', chunk, dt=.05, video=video, note=note)
        if result.meta.get('plan'):
            bad = [p for p in result.meta['plan'] if p.get('ik_ok') is False or p.get('speed_limited')]
            if bad:
                print('plan notes:', bad[:5])
        if result.meta.get('clipped'):
            print('clipped:', result.meta['clipped'])
    if result is not None:
        print(note, 'executed_rows=', result.meta.get('executed_rows'), 'steps=', result.meta.get('control_steps_chunk'), 'stopped=', result.stopped)
    return result


def move_to(target, spacing=.006, note='move'):
    now = np.asarray(r.get_obs(cameras=[], video='none').meta['proprio']['now'][7:14], float)
    return send_path(linear_poses(now, target, spacing), note=note)


def paper_xy(u, v):
    """Exemplar pixel center to world XY; sheets centered at (-0.1,0), image axes per spec."""
    mmpp = float(spec['static']['target_image']['mm_per_px']) / 1000.
    return (0.0135925 - (v + .5)*mmpp, 0.1135925 - (u + .5)*mmpp)


if __name__ == '__main__':
    print('status before:', r.status())
    # Startup calibration: clear the main sheet and visit the practice-sheet area.
    p = r.get_obs(cameras=[], video='none').meta['proprio']['now']
    current = np.asarray(p[7:14], float)
    hover = pose(-.1, -.1856, .18, 0.)
    result = send_path(linear_poses(current, hover, .006), note='travel to practice hover')
    if result:
        result.save(str(OUT/'calibration_travel'))
    print('tip now:', r.get_obs(cameras=[], video='none').meta['proprio']['now'][7:14])
